fn solve(input: Vec<char>) -> Vec<char> {
    // Helper: counts of each digit character as per good_count spec
    fn good_count(d: char) -> usize {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // input spec requires digit 0..9
        }
    }

    // Convert nat (usize) to Vec<char> (decimal digits, no leading zeros)
    fn nat_to_chars(mut n: usize) -> Vec<char> {
        if n == 0 {
            return vec!['0'];
        }
        let mut digits = vec![];
        while n > 0 {
            digits.push(((n % 10) as u8 + b'0') as char);
            n /= 10;
        }
        digits.reverse();
        digits
    }

    // Extract first two characters as digits, guaranteed by spec to be digits '0'..'9'
    let c1 = input[0];
    let c2 = input[1];

    // Compute the product of good counts
    let product = good_count(c1) * good_count(c2);

    // Convert product to decimal digit chars
    let mut result = nat_to_chars(product);

    // Append newline
    result.push('\n');

    result
}